INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss jedes XML-Dokument Tags enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Tags definieren Struktur"}, {"text": "Nein", "correct": false, "because": "Leer ist ungültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit XML?', 3, '[{"text": "Daten hierarchisch strukturieren", "correct": true, "because": "Tags organisieren Inhalt"}, {"text": "Daten komprimieren", "correct": false, "because": "Kein Fokus"}, {"text": "UI rendern", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile hat ein XML-Dokument?', 5, '[{"text": "Tags", "correct": true, "because": "Definieren Hierarchie"}, {"text": "Attribute", "correct": true, "because": "Erweitern Tags"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Binärcodes", "correct": false, "because": "Textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) XML ist validierbar. b) Tags können beliebig benannt werden.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) mit Schema, b) mit Regeln"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit XML?', 4, '[{"text": "Tag-Schließung", "correct": false, "because": "Muss ausgeglichen sein"}, {"text": "Validierung", "correct": false, "because": "Sichert Korrektheit"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob XML immer validiert werden muss?', 2, '[{"text": "Nein", "correct": true, "because": "Optional, aber empfohlen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich zur XML-Validierung?', 3, '[{"text": "XSD-Schema", "correct": true, "because": "Definiert Regeln"}, {"text": "Texteditor", "correct": false, "because": "Nur Anzeige"}, {"text": "Compiler", "correct": false, "because": "Für Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet XML?', 5, '[{"text": "Struktur", "correct": true, "because": "Hierarchisch organisiert"}, {"text": "Interoperabilität", "correct": true, "because": "Plattformunabhängig"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) XML ist schwer lesbar. b) Validierung ist Pflicht. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) subjektiv, b) optional"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) nicht pauschal"}, {"text": "Beides stimmt", "correct": false, "because": "Beides kontextuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für XML?', 4, '[{"text": "Tags", "correct": false, "because": "Grundstruktur"}, {"text": "Syntaxregeln", "correct": false, "because": "Sichern Gültigkeit"}, {"text": "Grafiksoftware", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist XML nur für große Datenmengen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Daten"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln gelten für XML-Tags?', 4, '[{"text": "Schließung erforderlich", "correct": true, "because": "Ausgeglichene Struktur"}, {"text": "Fallempfindlich", "correct": true, "because": "Case-sensitive"}, {"text": "Beliebige Reihenfolge", "correct": false, "because": "Hierarchie zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass XML schneller als JSON ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "JSON oft leichter"}, {"text": "Ja", "correct": false, "because": "XML schwerer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei XML?', 3, '[{"text": "Gültige Struktur", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) XML unterstützt Attribute. b) Tags sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Tags nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat XML?', 5, '[{"text": "Größerer Overhead", "correct": true, "because": "Tags erhöhen Größe"}, {"text": "Komplexere Validierung", "correct": true, "because": "Schema nötig"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Eher langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei XML unwichtig?', 3, '[{"text": "Tag-Namen", "correct": false, "because": "Definieren Struktur"}, {"text": "Schließende Tags", "correct": false, "because": "Sichern Gültigkeit"}, {"text": "Serverleistung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann XML ohne Validierung genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Well-formed reicht"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob XML case-insensitive ist?', 2, '[{"text": "Nein", "correct": true, "because": "Fallempfindlich"}, {"text": "Ja", "correct": false, "because": "Unterscheidet Groß/Klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für zusätzliche Tag-Infos?', 4, '[{"text": "Attribute", "correct": true, "because": "Erweitern Tags"}, {"text": "Arrays", "correct": false, "because": "JSON-spezifisch"}, {"text": "Loops", "correct": false, "because": "Programmierlogik"}]');
